    #[error("GitHub repository `{raw}` has more than one `/`")]
    TooManyParts { raw: String },
    #[error("GitHub repository `{raw}` has an invalid owner")]
    InvalidOwner { raw: String },
    #[error("GitHub repository `{raw}` has an invalid repository name")]
