impl ReleaseOperationId {
    pub fn registry_publish(package: ReleasePackageId, version: Version, registry: RegistryBindingId) -> Self {
        Self {
            package,
            role: ReleaseOperationRole::RegistryPublish { registry },
            version,
        }
    }

