    impl ReleaseDistributionMetadataV1 {
        const SCHEMA_VERSION: u8 = 1;

        fn from_manifest(intent: &ReleaseIntent, manifest: &ReleaseArtifactManifest) -> Result<Self, SuccessorError> {
            manifest.validate_for_intent(intent)?;
            let mut payloads = manifest
                .entries
                .iter()
                .filter_map(|entry| match &entry.slot {
                    ReleaseArtifactSlot::ProductAsset {
                        target,
                        file_name,
                        provenance_policy,
                        ..
                    } => Some(MetadataPayload {
                        target: *target,
                        file_name: file_name.clone(),
                        digest: entry.digest.clone(),
                        byte_length: entry.byte_length,
                        provenance_policy: provenance_policy.clone(),
                    }),
                    _ => None,
                })
                .collect::<Vec<_>>();
            payloads.sort_by_key(|payload| payload.target);
            let verification_policy = payloads
                .first()
                .expect("closed product roster contains product payloads")
                .provenance_policy
                .clone();
            let metadata = Self {
                schema_version: Self::SCHEMA_VERSION,
                product_release: intent.product_release.clone(),
                intent_digest: intent.digest.clone(),
                source_commit: intent.source_commit.clone(),
                payloads,
                verification_policy,
            };
            metadata.validate()?;
            Ok(metadata)
        }

        fn canonical_json(&self) -> Vec<u8> {
            serde_json::to_vec(self).expect("closed metadata serializes")
        }

        fn validate(&self) -> Result<(), SuccessorError> {
            if self.schema_version != Self::SCHEMA_VERSION
                || self.payloads.len() != ProductTarget::ALL.len()
                || self.payloads.windows(2).any(|pair| pair[0].target >= pair[1].target)
                || !ProductTarget::ALL.iter().zip(&self.payloads).all(|(target, payload)| {
                    target == &payload.target && is_safe_artifact_component(&payload.file_name)
                })
                || self
                    .payloads
                    .iter()
                    .any(|payload| payload.provenance_policy.validate().is_err())
                || self.verification_policy.validate().is_err()
                || self
                    .payloads
                    .iter()
                    .any(|payload| payload.provenance_policy != self.verification_policy)
            {
                return Err(SuccessorError::InvalidMetadata);
            }
            Ok(())
        }
    }

