    impl ReleaseArtifactManifest {
        const SCHEMA_VERSION: u8 = 1;

        fn new(intent: &ReleaseIntent, mut entries: Vec<ReleaseArtifactEntry>) -> Result<Self, SuccessorError> {
            entries.sort_by(|left, right| left.slot.cmp(&right.slot));
            if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot) {
                return Err(SuccessorError::DuplicateSlot);
            }
            if entries.iter().map(|entry| &entry.slot).ne(intent.slots.iter())
                || entries.iter().any(|entry| {
                    entry.source_commit != intent.source_commit || entry.provenance != *entry.slot.policy()
                })
            {
                return Err(SuccessorError::MismatchedManifest);
            }
            Ok(Self {
                schema_version: Self::SCHEMA_VERSION,
                intent_digest: intent.digest.clone(),
                source_commit: intent.source_commit.clone(),
                entries,
            })
        }

        fn validate_for_intent(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
            if self.schema_version != Self::SCHEMA_VERSION
                || self.intent_digest != intent.digest
                || self.source_commit != intent.source_commit
            {
                return Err(SuccessorError::MismatchedManifest);
            }
            Self::new(intent, self.entries.clone()).map(|_| ())
        }
    }

