/// Target registry or release location.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub enum PublishTarget {
    CratesIo,
    Npm {
        registry: Option<String>,
        /// The operator's explicit `publishConfig.access` from `package.json`,
        /// if set. `None` means npm's `publishConfig.access` was absent --
        /// distinct from an explicit `"public"`, which a bare bool couldn't
        /// represent (both collapsed to `false`, silently dropping an
        /// unscoped package's explicit `"public"` setting). When `Some`,
        /// `plan_publish` passes the corresponding `--access` flag rather
        /// than falling back to the `@scope/name`-implies-public heuristic.
        #[error("release operation prerequisites contain a cycle")]
        CyclicPrerequisites,
        #[error("artifact manifest differs from the intent-bound roster")]
        MismatchedManifest,
        #[error("distribution metadata is not canonical")]
        InvalidMetadata,
        #[error("checksum roster is not the exact payload plus metadata set")]
        InvalidChecksumRoster,
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        fn commit() -> CommitSha {
            CommitSha::parse(&"a".repeat(40)).unwrap()
        }

        fn policy() -> ProvenancePolicy {
            ProvenancePolicy::new(
                GitHubRepository::parse("callisto-rs/callisto").unwrap(),
                ".github/workflows/callisto-release.yml",
                commit(),
            )
            .unwrap()
        }

        fn release() -> ProductReleaseId {
            ProductReleaseId::from_coordinated_versions(
                ProductName::parse("callisto").unwrap(),
                [Version::semver(1, 2, 3), Version::semver(1, 2, 3)],
            )
            .unwrap()
        }

        fn slots(release: &ProductReleaseId) -> Vec<ReleaseArtifactSlot> {
            ProductTarget::ALL
                .iter()
                .map(|target| ReleaseArtifactSlot::ProductAsset {
                    release: release.clone(),
                    target: *target,
                    file_name: format!("callisto-{target:?}.tar.gz"),
                    provenance_policy: policy(),
                })
                .chain([
                    ReleaseArtifactSlot::ChecksumManifest {
                        release: release.clone(),
                        file_name: CHECKSUM_FILE_NAME.to_string(),
                        provenance_policy: policy(),
                    },
                    ReleaseArtifactSlot::ReleaseMetadata {
                        release: release.clone(),
                        file_name: METADATA_FILE_NAME.to_string(),
                        provenance_policy: policy(),
                    },
                ])
                .collect()
        }

        fn intent() -> ReleaseIntent {
            let release = release();
            let slots = slots(&release);
            let tag = ReleaseOperationId::ProductTag {
                release: release.clone(),
                tag: release.tag(),
            };
            let prepare = ReleaseOperationId::ForgePrepare {
                release: release.clone(),
                repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
            };
            let uploads = slots
                .iter()
                .map(|slot| {
                    ReleaseOperation::new(
                        ReleaseOperationId::ArtifactUpload {
                            release: release.clone(),
                            slot: slot.clone(),
                        },
                        vec![prepare.clone()],
                    )
                    .unwrap()
                })
                .collect::<Vec<_>>();
            let publish = ReleaseOperationId::ForgePublish {
                release: release.clone(),
                repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
            };
            let mut prerequisites = uploads.iter().map(|operation| operation.id.clone()).collect::<Vec<_>>();
            prerequisites.sort();
            let mut operations = vec![
                ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
                ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
            ];
            operations.extend(uploads);
            operations.push(ReleaseOperation::new(publish, prerequisites).unwrap());
            operations.sort_by(|left, right| left.id.cmp(&right.id));
            // Rebuild in canonical DAG order: tag, prepare, all uploads, publish.
            let mut canonical = Vec::new();
            let tag = operations
                .iter()
                .find(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
                .cloned()
                .unwrap();
            let prepare = operations
                .iter()
                .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
                .cloned()
                .unwrap();
            canonical.push(tag);
            canonical.push(prepare);
            canonical.extend(
                operations
                    .iter()
                    .filter(|operation| matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }))
                    .cloned(),
            );
            canonical.sort_by(|left, right| left.id.cmp(&right.id));
            // The stable order is identity sorted among all currently-ready nodes;
            // calculate it rather than baking a variant order into the test fixture.
            let edges: BTreeMap<_, _> = canonical
                .iter()
                .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
                .chain(std::iter::once((
                    operations
                        .iter()
                        .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                        .unwrap()
                        .id
                        .clone(),
                    operations
                        .iter()
                        .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                        .unwrap()
                        .prerequisites
                        .clone(),
                )))
                .collect();
            let ordered = stable_order(&edges).unwrap();
            let lookup: BTreeMap<_, _> = operations
                .into_iter()
                .chain(canonical)
                .map(|operation| (operation.id.clone(), operation))
                .collect();
            ReleaseIntent::new(
                release,
                commit(),
                ordered.into_iter().map(|id| lookup[&id].clone()).collect(),
                slots,
            )
            .unwrap()
        }

        #[test]
        fn product_identity_is_safe_semver_and_canonical() {
            assert!(ProductName::parse("Callisto").is_err());
            assert!(ProductName::parse("callisto/").is_err());
            assert_eq!(release().tag(), "callisto@1.2.3");
            assert!(ProductReleaseId::from_coordinated_versions(
                ProductName::parse("callisto").unwrap(),
                [Version::semver(1, 2, 3), Version::semver(1, 2, 4)],
            )
            .is_err());
            assert!(ProductReleaseId::new(
                ProductName::parse("callisto").unwrap(),
                Version::parse("1.2.3", VersionGrammar::Pep440).unwrap(),
            )
            .is_err());
            let wire = serde_json::to_value(release()).unwrap();
            assert!(serde_json::from_value::<ProductReleaseId>(wire).is_ok());
            assert_eq!(
                serde_json::to_string(&ProductTarget::X86_64UnknownLinuxMusl).unwrap(),
                "\"x86_64-unknown-linux-musl\""
            );
        }

        #[test]
        fn closed_roster_operations_and_wire_are_strict() {
            let intent = intent();
            assert_eq!(intent.slots.len(), 6);
            let mut wire = serde_json::to_value(&intent).unwrap();
            wire["unexpected"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<ReleaseIntent>(wire).is_err());
            let mut missing = intent.slots.clone();
            missing.pop();
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.operations.clone(),
                missing
            )
            .is_err());
            let mut duplicate = intent.slots.clone();
            duplicate.push(duplicate[0].clone());
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.operations.clone(),
                duplicate
            )
            .is_err());
            let mut wrong_target = intent.slots.clone();
            if let ReleaseArtifactSlot::ProductAsset { target, .. } = wrong_target
                .iter_mut()
                .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
                .unwrap()
            {
                *target = ProductTarget::Wasm32Wasip1;
            }
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.operations.clone(),
                wrong_target
            )
            .is_err());
            let mut unsafe_slot = intent.slots.clone();
            if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = unsafe_slot
                .iter_mut()
                .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
                .unwrap()
            {
                *file_name = "../callisto.tar.gz".to_string();
            }
            assert!(ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.operations.clone(),
                unsafe_slot
            )
            .is_err());
        }

        #[test]
        fn manifest_metadata_and_checksum_are_bound_without_circularity() {
            let intent = intent();
            let mut entries = intent
                .slots
                .iter()
                .cloned()
                .map(|slot| ReleaseArtifactEntry {
                    digest: ArtifactDigest::from_bytes(slot.file_name().as_bytes()),
                    byte_length: slot.file_name().len() as u64,
                    source_commit: commit(),
                    provenance: slot.policy().clone(),
                    slot,
                })
                .collect::<Vec<_>>();
            let manifest = ReleaseArtifactManifest::new(&intent, entries.clone()).unwrap();
            let metadata = ReleaseDistributionMetadataV1::from_manifest(&intent, &manifest).unwrap();
            let metadata_digest = ArtifactDigest::from_bytes(metadata.canonical_json());
            entries
                .iter_mut()
                .find(|entry| matches!(entry.slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
                .unwrap()
                .digest = metadata_digest.clone();
            let manifest = ReleaseArtifactManifest::new(&intent, entries).unwrap();
            let roster = checksum_roster(&intent, &manifest, metadata_digest).unwrap();
            assert_eq!(roster.len(), 5);
            assert!(roster.iter().all(|entry| entry.file_name != CHECKSUM_FILE_NAME));
            assert!(roster.iter().any(|entry| entry.file_name == METADATA_FILE_NAME));
            assert!(roster.iter().all(|entry| entry.line().contains("  ")));
            let mut forged = manifest.clone();
            forged.entries[0].source_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
            assert!(forged.validate_for_intent(&intent).is_err());
            let mut metadata_wire = serde_json::to_value(metadata).unwrap();
            metadata_wire["unknown"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<ReleaseDistributionMetadataV1>(metadata_wire).is_err());
        }
    }
}

